# Git change set of a remote project folder (generated by gitRemoteScript; placeholders @...@). Runs after the prelude.
# Frames: git, home (values), version, revparse, config, status, numstat, patch (Full only), untracked, c<i> (Full only).
# Stops: nodir, nogit, version, oldgit, norepo, revparse, config, unsafe, status.
cd -- @DIR@ 2>/dev/null || cb_stop nodir
cb_full=@FULL@
cb_os=$(uname -s 2>/dev/null) || cb_os=

# --- Finding git (as acpFindGit: PATH, then the usual directories; macOS's /usr/bin/git stub only with the tools) ---
cb_usable() {
    [ -f "$1" ] && [ -x "$1" ] || return 1
    if [ "$cb_os" = Darwin ] && [ "$1" = /usr/bin/git ]; then
        [ -x /Library/Developer/CommandLineTools/usr/bin/git ] || [ -x /Applications/Xcode.app/Contents/Developer/usr/bin/git ] || return 1
    fi
    return 0
}
cb_git=
IFS=:
for cb_p in $PATH /usr/bin /usr/local/bin /opt/homebrew/bin; do
    case $cb_p in /*) ;; *) continue;; esac
    if cb_usable "$cb_p/git"; then cb_git=$cb_p/git; break; fi
done
unset IFS
[ -n "$cb_git" ] || cb_stop nogit
cb_value git "$cb_git"
cb_value home "$HOME"

# --- Version (bare, like gitStepVersion) ---
cb_run version 65536 65536 "$cb_git" --version
cb_vmaj=0; cb_vmin=0
IFS=' .' read -r cb_w1 cb_w2 cb_vmaj cb_vmin cb_rest < "$cb_d/o" || :
case $cb_vmaj in ''|*[!0-9]*) cb_vmaj=0;; esac
case $cb_vmin in ''|*[!0-9]*) cb_vmin=0;; esac
cb_ge() { [ "$cb_vmaj" -gt "$1" ] || { [ "$cb_vmaj" -eq "$1" ] && [ "$cb_vmin" -ge "$2" ]; }; }
[ "$cb_rc" = 0 ] || cb_stop version
cb_ge @MINMAJ@ @MINMIN@ || cb_stop oldgit

# --- The .git hint (as acpGitWorkTreeRoot: the logical path, then the physical one); no git without it ---
cb_walk() {
    cb_h=$1
    while [ -n "$cb_h" ]; do
        if [ -e "$cb_h/.git" ]; then return 0; fi
        cb_h=${cb_h%/*}
    done
    [ -e /.git ]
}
cb_walk "$(pwd)" || cb_walk "$(pwd -P)" || cb_stop norepo

# --- Global options (gitCommand): positional parameters, so that any string is one argument ---
set -- --no-pager --no-optional-locks
if cb_ge @LAZYMAJ@ @LAZYMIN@; then set -- "$@" --no-lazy-fetch; fi
set -- "$@" @SAFECONFIG@

cb_run revparse 65536 65536 "$cb_git" "$@" rev-parse --show-toplevel --show-prefix --show-object-format
[ "$cb_rc" = 0 ] || cb_stop revparse
cb_fmt=$(tail -n 1 < "$cb_d/o")
cb_cdup=$("$cb_git" "$@" rev-parse --show-cdup </dev/null 2>/dev/null) || cb_cdup=

# --- Filter drivers: each is neutralized; a name with "=" can't be, then nothing else runs ---
cb_run config @CFGCAP@ 65536 "$cb_git" "$@" config -z --name-only --get-regexp '^filter\.'
case $cb_rc in 0|1) ;; *) cb_stop config;; esac
cb_truncated @CFGCAP@ && cb_stop config
tr '\000' '\n' < "$cb_d/o" > "$cb_d/filters"
cb_seen='
'
cb_unsafe=0
while IFS= read -r cb_k; do
    cb_n=${cb_k#filter.}
    cb_n=${cb_n%.*}
    case $cb_seen in *"
$cb_n
"*) continue;; esac
    cb_seen="$cb_seen$cb_n
"
    case $cb_n in *=*) cb_unsafe=1;; esac
    set -- "$@" -c "filter.$cb_n.clean=" -c "filter.$cb_n.smudge=" -c "filter.$cb_n.process=" -c "filter.$cb_n.required=false"
done < "$cb_d/filters"
[ "$cb_unsafe" = 0 ] || cb_stop unsafe

# --- Status ---
cb_run status @MAXOUT@ 65536 "$cb_git" "$@" @STATUSARGS@
{ [ "$cb_rc" = 0 ] && ! cb_truncated @MAXOUT@; } || cb_stop status
mv -f "$cb_d/o" "$cb_d/status"

# HEAD, or the empty tree without commits (the first field is always "# branch.oid ...")
cb_base=HEAD
if [ "$(head -c 64 < "$cb_d/status" | tr '\000' '\n' 2>/dev/null | head -n 1)" = '# branch.oid (initial)' ]; then
    if [ "$cb_fmt" = sha256 ]; then cb_base=@EMPTY256@; else cb_base=@EMPTY1@; fi
fi

# --- Line counts and the patch, if tracked files changed (a superset of gitTrackedChangesQ) ---
if tr '\000' '\n' < "$cb_d/status" 2>/dev/null | grep -q '^[12u] '; then
    cb_run numstat @MAXOUT@ 65536 "$cb_git" "$@" diff "$cb_base" --numstat -z @DIFFOPTS@ -- .
    if [ "$cb_full" = 1 ]; then
        cb_run patch @MAXOUT@ 65536 "$cb_git" "$@" diff "$cb_base" @DIFFOPTS@ @PATCHOPTS@ -- .
    fi
    : > "$cb_d/o"; : > "$cb_d/e"
fi

# --- Untracked files: the first @MAXFILES@ "? " entries in git's order (a superset of the listed ones), in batched passes
# (forks are slow: one process per file only for the binary check without a NUL-safe awk, and for the text of Full
# change sets). Paths with newlines are not found (gitRemoteUntracked marks them unreadable). Records in frame
# "untracked" (NUL-terminated fields): index kind size lines target path; kinds: link missing other unreadable toolarge
# notread empty binary text. Full: the text of file <index> in frame c<index>. ---
tr '\000' '\n' < "$cb_d/status" 2>/dev/null | sed -n 's/^? //p' | head -n @MAXFILES@ > "$cb_d/cand"
: > "$cb_d/uinfo"
: > "$cb_d/reg"
cb_rec() {  # index kind size lines target path
    printf '%s\000%s\000%s\000%s\000%s\000%s\000' "$1" "$2" "$3" "$4" "$5" "$6" >> "$cb_d/uinfo"
}
# Pass 1 (builtins): kinds; regular readable files go to the list "reg" (index TAB path)
cb_i=0
while IFS= read -r cb_p; do
    case $cb_p in */) continue;; esac
    cb_i=$((cb_i + 1))
    cb_f=./$cb_cdup$cb_p
    if [ -L "$cb_f" ]; then
        cb_tgt=
        if [ -e "$cb_f" ]; then
            cb_tgt=$(readlink -f -- "$cb_f" 2>/dev/null) || cb_tgt=$(realpath -- "$cb_f" 2>/dev/null) || cb_tgt=$(readlink -- "$cb_f" 2>/dev/null) || cb_tgt=
        fi
        cb_rec "$cb_i" link 0 1 "$cb_tgt" "$cb_p"
    elif [ ! -e "$cb_f" ]; then cb_rec "$cb_i" missing 0 0 '' "$cb_p"
    elif [ ! -f "$cb_f" ]; then cb_rec "$cb_i" other 0 0 '' "$cb_p"
    elif [ ! -r "$cb_f" ]; then cb_rec "$cb_i" unreadable 0 0 '' "$cb_p"
    else printf '%s\t%s\n' "$cb_i" "$cb_p" >> "$cb_d/reg"
    fi
done < "$cb_d/cand"
# Pass 2: sizes, one per line of "reg" in "sizes" ("big" over the size cap, found with find so that wc never reads
# such files; -1 for a file that is gone)
: > "$cb_d/large"
: > "$cb_d/sizes"
set --
while IFS= read -r cb_l; do set -- "$@" "./$cb_cdup${cb_l#*	}"; done < "$cb_d/reg"
if [ "$#" -gt 0 ]; then
    find "$@" -prune -size +@MAXFILE@c -print > "$cb_d/large" 2>/dev/null
    cb_large="
$(cat "$cb_d/large")
"
    set --
    while IFS= read -r cb_l; do
        cb_f=./$cb_cdup${cb_l#*	}
        case $cb_large in *"
$cb_f
"*) ;; *) set -- "$@" "$cb_f";; esac
    done < "$cb_d/reg"
    # wc lists the files in order ("size name"; "total" last); a file that is gone has no line
    if [ "$#" -gt 0 ]; then wc -c -- "$@" 2>/dev/null; fi | awk -v list="$cb_d/reg" -v cdup="$cb_cdup" -v large="$cb_d/large" '
        BEGIN { while ((getline l < large) > 0) big[l] = 1; have = next_expected() }
        function next_expected() {
            while ((getline e < list) > 0) {
                e = "./" cdup substr(e, index(e, "\t") + 1)
                if (e in big) print "big"; else return 1
            }
            return 0
        }
        {
            line = $0; sub(/^[ \t]+/, "", line)
            n = line; sub(/[^0-9].*$/, "", n)
            name = substr(line, length(n) + 2)
            while (have && name != e) { print -1; have = next_expected() }
            if (have) { print n; have = next_expected() }
        }
        END { while (have) { print -1; have = next_expected() } }' > "$cb_d/sizes"
fi
# Pass 3 (builtins): caps and the read budget; files to read go to "toread" (index TAB size TAB path)
: > "$cb_d/toread"
cb_budget=@BUDGET@
exec 4< "$cb_d/sizes"
while IFS= read -r cb_l; do
    IFS= read -r cb_sz <&4 || cb_sz=-1
    cb_i=${cb_l%%	*}; cb_p=${cb_l#*	}
    case $cb_sz in
        big) cb_rec "$cb_i" toolarge 0 0 '' "$cb_p"; continue;;
        ''|-*|*[!0-9]*) cb_rec "$cb_i" unreadable 0 0 '' "$cb_p"; continue;;
    esac
    if [ "$cb_sz" -gt @MAXFILE@ ]; then cb_rec "$cb_i" toolarge 0 0 '' "$cb_p"
    elif [ "$cb_sz" -gt "$cb_budget" ]; then cb_rec "$cb_i" notread 0 0 '' "$cb_p"
    elif [ "$cb_sz" -eq 0 ]; then cb_rec "$cb_i" empty 0 0 '' "$cb_p"
    else
        cb_budget=$((cb_budget - cb_sz))
        printf '%s\t%s\t%s\n' "$cb_i" "$cb_sz" "$cb_p" >> "$cb_d/toread"
    fi
done < "$cb_d/reg"
exec 4<&-
# Pass 4: one line "lines nul" per file to read (nul: 1 or 0 for a NUL byte in the first @BINCHECK@ bytes, -1 if awk
# drops NUL bytes; lines: -1 if the file could not be read)
awk -v list="$cb_d/toread" -v cdup="$cb_cdup" -v head=@BINCHECK@ -v nulsafe=@NULSAFE@ '
    BEGIN {
        z = sprintf("%c", 0); safe = (nulsafe == 1 && length(z) == 1 && length("a" z "b") == 3)
        while ((getline e < list) > 0) {
            sub(/^[^\t]*\t[^\t]*\t/, "", e); f = "./" cdup e
            n = 0; pos = 0; nul = (safe ? 0 : -1)
            while ((r = (getline l < f)) > 0) {
                n++
                if (nul == 0 && pos < head) { k = index(l, z); if (k > 0 && pos + k <= head) nul = 1 }
                pos += length(l) + 1
                if (nul == 1) break
            }
            close(f)
            print (r < 0 ? -1 : n), nul
        }
        exit
    }' > "$cb_d/counts"
# Pass 5: records; the binary check with od where awk could not do it; the text of Full change sets
exec 4< "$cb_d/counts"
while IFS= read -r cb_l; do
    cb_lines=-1; cb_nul=-1
    IFS=' ' read -r cb_lines cb_nul <&4 || :
    cb_i=${cb_l%%	*}; cb_r=${cb_l#*	}; cb_sz=${cb_r%%	*}; cb_p=${cb_r#*	}
    cb_f=./$cb_cdup$cb_p
    case $cb_lines in ''|-*) cb_rec "$cb_i" unreadable 0 0 '' "$cb_p"; continue;; esac
    if [ "$cb_nul" = -1 ]; then
        if od -An -v -tx1 -N @BINCHECK@ < "$cb_f" 2>/dev/null | grep -q ' 00'; then cb_nul=1; else cb_nul=0; fi
    fi
    if [ "$cb_nul" = 1 ]; then cb_rec "$cb_i" binary "$cb_sz" 0 '' "$cb_p"; continue; fi
    cb_rec "$cb_i" text "$cb_sz" "$cb_lines" '' "$cb_p"
    if [ "$cb_full" = 1 ]; then
        # Exactly cb_sz bytes (conv=sync pads a shorter read), so that the frame stays intact if the file changed; files
        # are always opened by the shell (uutils, e.g. on Ubuntu, rejects file name operands that are not UTF-8)
        printf 'F c%s - %s 0 0 0\n' "$cb_i" "$cb_sz"
        dd bs="$cb_sz" count=1 conv=sync < "$cb_f" 2>/dev/null || dd bs="$cb_sz" count=1 < /dev/zero 2>/dev/null
        printf '\n'
    fi
done < "$cb_d/toread"
exec 4<&-
cb_emit untracked - "$cb_d/uinfo" /dev/null @MAXOUT@ 0
cb_end
